"""Unit tests for the MEPS dataset build — synthetic panels only."""
from __future__ import annotations

import pytest

from outcome_prediction.meps.build import (
    LABEL, PanelMismatch, build, load_panel, resolve_dx_column,
)
from outcome_prediction.tests.conftest import person

# The 25 features in the contract's column order (design.md §3), preceded by the IDs and
# followed by the survey design variables, flags and label — the prototype's exact layout.
EXPECTED_COLUMNS = [
    "dupersid", "panel", "sex", "racethx", "regiony1", "agey1x", "inscovy1", "povcaty1",
    "ipdisy1", "ipngtdy1", "ertoty1", "obtotvy1", "optotvy1", "hhtotdy1", "rxtoty1",
    "totexpy1", "longwt", "varstr", "varpsu", "hibpdx", "chddx", "angidx", "midx",
    "ohrtdx", "strkdx", "emphdx", "diabdx", "arthdx", "asthdx", "choldx", LABEL,
]


def test_keeps_adults_observed_in_both_years(write_panel):
    dta = write_panel("h1.dta", [
        person("A", 21, age=18),
        person("B", 21, age=17),               # child: excluded
        person("C", 21, ipdis1=-1),            # year-1 count missing: excluded
        person("D", 21, ipdis2=-1),            # year-2 count missing: excluded
        person("E", 21, age=85),
    ])
    df, _ = build({21: dta})
    assert sorted(df.dupersid) == ["A", "E"]


def test_label_is_any_year2_discharge_and_year2_count_is_dropped(write_panel):
    dta = write_panel("h1.dta", [
        person("A", 21, ipdis2=0), person("B", 21, ipdis2=1), person("C", 21, ipdis2=3),
    ])
    df, _ = build({21: dta})
    assert dict(zip(df.dupersid, df[LABEL])) == {"A": 0, "B": 1, "C": 1}
    assert "ipdisy2" not in df.columns


def test_dx_flags_recode_meps_yes_no_and_missing(write_panel):
    dta = write_panel("h1.dta", [
        person("YES", 21, dx={"HIBPDXY1": 1}),
        person("NO", 21, dx={"HIBPDXY1": 2}),
        person("INAPPLICABLE", 21, dx={"HIBPDXY1": -1}),
        person("DONT_KNOW", 21, dx={"HIBPDXY1": -8}),
    ])
    df, _ = build({21: dta})
    assert dict(zip(df.dupersid, df.hibpdx)) == {
        "YES": 1, "NO": 0, "INAPPLICABLE": 0, "DONT_KNOW": 0}


def test_drifted_dx_column_is_resolved_and_reported(write_panel):
    dta = write_panel("h1.dta", [person("A", 23, dx={"DIABDXY1": 1})],
                      rename={"DIABDXY1": "DIABDXY1_M18"})
    df, info = load_panel(dta, 23)
    assert df.diabdx.tolist() == [1]
    assert info["dx_columns"]["diabdx"] == {
        "column": "DIABDXY1_M18", "candidates": ["DIABDXY1_M18"]}


def test_resolve_dx_column_picks_first_sorted_and_reports_all_candidates():
    chosen, candidates = resolve_dx_column(
        ["DIABDXY2", "DIABDXY1_M18", "DIABDXY1", "SEX"], "DIABDX")
    assert chosen == "DIABDXY1"
    assert candidates == ["DIABDXY1", "DIABDXY1_M18"]


def test_resolve_dx_column_raises_when_absent():
    with pytest.raises(KeyError, match="CHDDX"):
        resolve_dx_column(["SEX", "CHDDXY2"], "CHDDX")


def test_wrong_panel_in_file_is_rejected(write_panel):
    dta = write_panel("h1.dta", [person("A", 24)])
    with pytest.raises(PanelMismatch, match=r"\[24\], expected \[21\]"):
        load_panel(dta, 21)


def test_output_layout_and_report(write_panel):
    p21 = write_panel("h1.dta", [person("A", 21, ipdis2=1), person("B", 21, age=10)])
    p22 = write_panel("h2.dta", [person("C", 22), person("D", 22)])
    df, report = build({21: p21, 22: p22})

    assert list(df.columns) == EXPECTED_COLUMNS
    assert report["panels"][21] | {"dx_columns": None} == {
        "file": "h1.dta", "persons_in_file": 2, "adults_kept": 1, "events": 1,
        "dx_columns": None}
    assert report["panels"][22]["adults_kept"] == 2
    assert report["total"] == {"rows": 3, "columns": 31, "events": 1, "rate": 0.3333}

"""M1 acceptance: reproduce the research prototype's MEPS dataset and HC-252 dictionary
exactly (docs/phase8/prd.md §9 criteria 1 and 3; prototype-baseline.md §3.1, §3.4).

Needs the real MEPS cache — self-skips without it. Populate it with:
    python -m outcome_prediction.meps.download
"""
from __future__ import annotations

import pytest

from outcome_prediction.meps import LONGITUDINAL_PANELS
from outcome_prediction.meps.build import LABEL, build
from outcome_prediction.meps.dictionary import storage_counts, variable_dictionary

# panel: (persons in file, adults kept, events) — prototype-baseline.md §3.1
EXPECTED = {
    21: (15_617, 11_174, 880),
    22: (14_541, 10_613, 940),
    23: (14_067, 10_447, 989),
    24: (9_797, 7_533, 592),
    25: (6_078, 4_730, 377),
    26: (6_741, 5_350, 453),
    27: (8_292, 6_513, 589),
}


@pytest.fixture(scope="module")
def built(meps_cache):
    panels = {p: meps_cache / f"h{n}.dta" for p, n in LONGITUDINAL_PANELS.items()}
    return build(panels)


def test_dataset_totals(built):
    df, _ = built
    assert df.shape == (56_360, 31)
    assert int(df[LABEL].sum()) == 4_820


@pytest.mark.parametrize("panel", sorted(EXPECTED))
def test_dataset_per_panel(built, panel):
    _, report = built
    info = report["panels"][panel]
    assert (info["persons_in_file"], info["adults_kept"], info["events"]) == EXPECTED[panel]


def test_every_dx_flag_resolves_to_exactly_one_candidate(built):
    """design.md §11 defect 6: resolution by prefix is fragile. Today it is unambiguous in
    every panel; this fails if a future file introduces a second matching column."""
    _, report = built
    ambiguous = {(p, flag): v["candidates"]
                 for p, info in report["panels"].items()
                 for flag, v in info["dx_columns"].items() if len(v["candidates"]) > 1}
    assert ambiguous == {}


def test_hc252_dictionary(meps_cache):
    d = variable_dictionary(meps_cache / "h252.dta")
    assert len(d) == 2_648
    assert storage_counts(d) == {
        "int8": 1_603, "int16": 611, "int32": 383, "float64": 25,
        "str2": 21, "str3": 2, "str9": 2, "str10": 1,
    }

"""Model artifacts: write, verify, load (design.md §8; decisions.md O17, O18).

    models/<model_id>/
      model.joblib        gradient boosting (release model, all panels)
      comparison.joblib   logistic regression comparison model (O18)
      metadata.json       contract, features, data checksums, versions, validation metrics,
                          training-score quantiles (for percentiles)
      MANIFEST.sha256     sha256 of every other file; verified BEFORE anything is deserialised

joblib/pickle loading executes code, so integrity comes first: a missing, changed or unlisted
file means the artifact is refused, not loaded.
"""
from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path

import joblib
import numpy as np

MODEL = "model.joblib"
COMPARISON = "comparison.joblib"
METADATA = "metadata.json"
MANIFEST = "MANIFEST.sha256"


class ArtifactIntegrityError(RuntimeError):
    """The artifact directory doesn't match its manifest; it must not be loaded."""


@dataclass(frozen=True)
class Artifact:
    path: Path
    model: object
    comparison: object
    metadata: dict


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_artifact(directory: Path, model, comparison, metadata: dict) -> Path:
    directory.mkdir(parents=True, exist_ok=False)   # never overwrite an existing artifact
    joblib.dump(model, directory / MODEL)
    joblib.dump(comparison, directory / COMPARISON)
    (directory / METADATA).write_text(json.dumps(metadata, indent=2, sort_keys=True) + "\n")
    lines = [f"{_sha256(directory / name)}  {name}" for name in sorted((MODEL, COMPARISON, METADATA))]
    (directory / MANIFEST).write_text("\n".join(lines) + "\n")
    return directory


def verify_artifact(directory: Path) -> None:
    manifest = directory / MANIFEST
    if not manifest.exists():
        raise ArtifactIntegrityError(f"{directory}: no {MANIFEST}")
    listed = {}
    for line in manifest.read_text().splitlines():
        digest, _, name = line.partition("  ")
        if not digest or not name or "/" in name or name.startswith("."):
            raise ArtifactIntegrityError(f"{directory}: malformed manifest line {line!r}")
        listed[name] = digest

    present = {p.name for p in directory.iterdir() if p.is_file() and p.name != MANIFEST}
    if unlisted := present - listed.keys():
        raise ArtifactIntegrityError(f"{directory}: files not in manifest: {sorted(unlisted)}")
    if missing := {MODEL, COMPARISON, METADATA} - listed.keys():
        raise ArtifactIntegrityError(f"{directory}: manifest omits required {sorted(missing)}")
    for name, digest in listed.items():
        path = directory / name
        if not path.exists():
            raise ArtifactIntegrityError(f"{directory}: {name} listed but missing")
        if _sha256(path) != digest:
            raise ArtifactIntegrityError(f"{directory}: {name} does not match its manifest checksum")


def load_artifact(directory: Path) -> Artifact:
    verify_artifact(directory)
    return Artifact(
        path=directory,
        model=joblib.load(directory / MODEL),
        comparison=joblib.load(directory / COMPARISON),
        metadata=json.loads((directory / METADATA).read_text()),
    )


def score_quantiles(scores: np.ndarray) -> list[float]:
    """101 quantiles (0th..100th) of the training population's scores."""
    return np.quantile(scores, np.linspace(0, 1, 101)).tolist()


def risk_percentile(score: float, quantiles: list[float]) -> int:
    """Percentile (0–100) of `score` within the training population: the share of training
    scores at or below it, to the nearest quantile."""
    return int(np.searchsorted(np.asarray(quantiles), score, side="right") - 1).__index__() \
        if score >= quantiles[0] else 0

"""Fitting the gradient-boosting model and the comparison model (FR-M1, FR-M2).

Importable functions, not only CLIs: the lab (M3) calls these (decisions.md O29).
"""
from __future__ import annotations

from dataclasses import dataclass

import numpy as np
import pandas as pd
from sklearn.ensemble import HistGradientBoostingClassifier
from sklearn.linear_model import LogisticRegression

from outcome_prediction.model import (
    COMPARISON_PARAMS, GBM_PARAMS, LABEL, categorical_indices, comparison_matrix,
    feature_matrix, split_masks,
)


def fit_gbm(X: pd.DataFrame, y: np.ndarray) -> HistGradientBoostingClassifier:
    return HistGradientBoostingClassifier(
        **GBM_PARAMS, categorical_features=categorical_indices()).fit(X, y)


def fit_comparison(B: np.ndarray, y: np.ndarray) -> LogisticRegression:
    return LogisticRegression(**COMPARISON_PARAMS).fit(B, y)


@dataclass(frozen=True)
class Fitted:
    gbm: HistGradientBoostingClassifier
    comparison: LogisticRegression


def fit_validation(table: pd.DataFrame) -> Fitted:
    """Both models on the training panels only (21–25) — the models whose test-panel metrics
    are reported."""
    train, _ = split_masks(table)
    y = table[LABEL].to_numpy()
    return Fitted(gbm=fit_gbm(feature_matrix(table)[train], y[train]),
                  comparison=fit_comparison(comparison_matrix(table)[train], y[train]))


def fit_release(table: pd.DataFrame) -> Fitted:
    """Both models refit on all panels, for serving. Their own held-out performance is
    unknown by construction (design.md §11, defect 5)."""
    y = table[LABEL].to_numpy()
    return Fitted(gbm=fit_gbm(feature_matrix(table), y),
                  comparison=fit_comparison(comparison_matrix(table), y))

